get_ecommerce_settings.code:
import (
	"fmt"
)

resp, err := client.EcommerceSettings().GetEcommerceSettings(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["ecommerce_settings"].(map[string]any)
pricing := settings["pricing"].(map[string]any)
fmt.Println(settings["product_inventory"].(map[string]any)["update_stock"], pricing["minimum_purchase_amount"], pricing["payment_terms"])
for _, row := range settings["order_flags"].([]any) {
	orderFlag := row.(map[string]any)
	fmt.Println(orderFlag["id"], orderFlag["name"])
}

