	},
}, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["ecommerce_settings"].(map[string]any)
fmt.Println(settings["continue_shopping"].(map[string]any)["continue_shopping_target"], settings["order_filters"].(map[string]any)["default_payment_status"])

